/bin/bash -lc "python - <<'PY'
import os, requests, json, textwrap
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip(); base='https://usegalaxy.org'
for label,tid in [('DESeq2','toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3'),('gProfiler','toolshed.g2.bx.psu.edu/repos/iuc/gprofiler_gost/gprofiler_gost/0.1.7+galaxy11')]:
 data=requests.get(base+'/api/tools/'+requests.utils.quote(tid, safe=''), params={'key':key,'io_details':'true'}, timeout=30).json()
 print('\\n###', label)
 def walk(inputs, indent=0):
  for inp in inputs:
   if inp.get('type') in ('repeat','conditional','section'):
    print(' '*indent, inp.get('name'), inp.get('type'), inp.get('label'))
    if inp.get('type')=='conditional':
     print(' '*indent,' test_param',inp.get('test_param'))
     for case in inp.get('cases',[]):
      print(' '*indent,' case', case.get('value'))
      walk(case.get('inputs',[]), indent+4)
    else:
     walk(inp.get('inputs',[]), indent+2)
   else:
    d={k:inp.get(k) for k in ['name','type','label','value','optional','argument','format','multiple'] if k in inp}
    if 'options' in inp:
     opts=inp['options']
     if isinstance(opts, list): d['options']=opts[:10]
     else: d['options']=str(opts)[:200]
    print(' '*indent, json.dumps(d)[:1200])
 walk(data.get('inputs',[]))
 print('outputs:', json.dumps(data.get('outputs',[]), indent=2)[:4000])
PY"
